/**
 * Dota 2 SkinForge — Armory Catalog & Slot Definition Resolver
 *
 * Source of truth for heroes is `data/heroes_armory.json`, regenerated by `npm run armory`
 * from the game's own `items_game.txt`. Each hero owns its slots directly, and every slot
 * owns its items:
 *
 *   hero.slots[] -> { slot, title, empty_img, mods[] }
 *   mod          -> { id, name, rarity, img }
 *
 * Non-hero categories come from `data/other_armory.json`, which uses the same shape; each
 * entry carries its own display metadata (`name`, `img`, `g`), mapped onto `CatalogEntry.group`.
 *
 * Results are memoised per tag and shared between callers, so treat them as read-only.
 */

import heroesArmoryData from '../../../data/heroes_armory.json'
import otherArmoryData from '../../../data/other_armory.json'
import { HERO_ALIASES, getCanonicalHero } from '../constants/heroAliases'
import { isHeroAttribute, normalizeEntityTag, type ArmoryEntry, type ArmoryItem, type ArmorySlot, type CatalogEntry } from './armoryTypes'
import { getItemRarityKey, rarityRank } from './rarityConfig'

export { normalizeEntityTag, type ArmoryEntry, type ArmoryItem, type ArmorySlot, type CatalogEntry }

interface RawCategoryEntry {
  tag?: string
  name?: string
  img?: string
  g?: 'world' | 'interface' | string
  slots: ArmorySlot[]
}

const rawHeroArmory = (heroesArmoryData as unknown as Record<string, ArmoryEntry>) || {}
const rawOtherArmory = (otherArmoryData as unknown as Record<string, RawCategoryEntry>) || {}

export function getRawHeroArmory(): Record<string, ArmoryEntry> {
  return rawHeroArmory
}

const armoryIndex = new Map<string, ArmoryEntry>()
for (const [key, entry] of Object.entries(rawHeroArmory)) {
  armoryIndex.set(normalizeEntityTag(key), entry)
  if (entry?.tag) armoryIndex.set(normalizeEntityTag(entry.tag), entry)
  armoryIndex.set(normalizeEntityTag(getCanonicalHero(key)), entry)
}

/** Look up a hero's raw armory entry by UI key, tag, or canonical Valve hero name. */
export function getRawHeroEntry(heroTag?: string | null): ArmoryEntry | undefined {
  if (!heroTag) return undefined
  const key = normalizeEntityTag(heroTag)
  return armoryIndex.get(key) ?? armoryIndex.get(normalizeEntityTag(getCanonicalHero(heroTag)))
}

const otherArmoryIndex = new Map<string, RawCategoryEntry>()
const categoryNames = new Map<string, string>()
const categories: CatalogEntry[] = []

for (const [key, entry] of Object.entries(rawOtherArmory)) {
  const tag = entry.tag ?? key
  otherArmoryIndex.set(normalizeEntityTag(key), entry)
  otherArmoryIndex.set(normalizeEntityTag(tag), entry)
  if (entry.name) categoryNames.set(tag.toLowerCase(), entry.name)
  categories.push({
    tag,
    name: entry.name,
    img: entry.img,
    group: entry.g === 'interface' ? 'interface' : entry.g === 'world' ? 'world' : undefined
  })
}

export function formatCatalogName(tag?: string | null): string {
  if (!tag) return ''
  const category = categoryNames.get(tag.toLowerCase())
  if (category) return category
  return tag
    .split(/[_\s-]+/)
    .map((w) => w.charAt(0).toUpperCase() + w.slice(1))
    .join(' ')
}

/** Filter out removed slots (taunt, Diretide shimmer costumes) and empty category slots. */
function cleanSlots(entry: { tag?: string; slots: ArmorySlot[] }): ArmoryEntry {
  return {
    tag: entry.tag,
    slots: entry.slots
      .filter((s) => s.slot !== 'taunt')
      .map((s) => ({
        ...s,
        mods: s.mods.filter((m) => !m.name.toLowerCase().includes('diretide shimmer costume'))
      }))
      .filter((s) => s.mods.length > 0)
  }
}

function byRarity(a: ArmoryItem, b: ArmoryItem): number {
  return rarityRank(getItemRarityKey(b)) - rarityRank(getItemRarityKey(a))
}

/**
 * Rarest item first inside every slot. The sort is stable, so items of the same rarity keep
 * their armory order — which is what keeps a style variant next to its base item.
 */
function sortModsByRarity(entry: ArmoryEntry): ArmoryEntry {
  return {
    ...entry,
    slots: entry.slots.map((slot) => ({ ...slot, mods: [...slot.mods].sort(byRarity) }))
  }
}

const prepared = new Map<string, ArmoryEntry | null>()

/**
 * Resolve a hero or non-hero category to its slot armory.
 * Returns `null` when nothing is known about the tag. The result is memoised per tag —
 * callers must not mutate it.
 */
export function resolveArmoryEntry(tag?: string | null, catalogEntry?: CatalogEntry | null): ArmoryEntry | null {
  if (!tag) return null

  const key = normalizeEntityTag(tag)
  const cached = prepared.get(key)
  if (cached !== undefined) return cached

  const entry = armoryIndex.get(key) ?? (catalogEntry?.tag ? armoryIndex.get(normalizeEntityTag(catalogEntry.tag)) : undefined)
  const other = entry ? undefined : otherArmoryIndex.get(key)
  const resolved = entry ? sortModsByRarity(cleanSlots(entry)) : other ? sortModsByRarity(cleanSlots(other)) : null

  prepared.set(key, resolved)
  return resolved
}

/** Other names that resolve to this hero's schema owner, so search can match them. */
function aliasesFor(tag: string): string[] {
  const canonical = getCanonicalHero(tag)
  return Object.entries(HERO_ALIASES)
    .filter(([key, target]) => target === canonical && key !== tag)
    .map(([key]) => key)
}

const heroes: CatalogEntry[] = Object.entries(rawHeroArmory).map(([tag, entry]) => ({
  tag,
  name: formatCatalogName(tag),
  attribute: isHeroAttribute(entry.attribute) ? entry.attribute : undefined,
  alias: aliasesFor(tag)
}))

export function listHeroes(): CatalogEntry[] {
  return heroes
}

export function listCategories(): CatalogEntry[] {
  return categories
}
